def transform(grid):
    """Overlay two equal panels split by a centered solid divider."""
    h, w = len(grid), len(grid[0])
    panels = None

    # A solid center row or column separates equal-sized panels.
    if h % 2 == 1:
        r = h // 2
        if all(v == grid[r][0] for v in grid[r]):
            panels = (grid[:r], grid[r + 1:])
    if panels is None and w % 2 == 1:
        c = w // 2
        if all(row[c] == grid[0][c] for row in grid):
            panels = ([row[:c] for row in grid], [row[c + 1:] for row in grid])
    if panels is None:
        raise ValueError("no centered solid divider")

    a, b = panels
    if len(a) != len(b) or any(len(ra) != len(rb) for ra, rb in zip(a, b)):
        raise ValueError("panels have different shapes")
    # The demos show 2 precisely where both aligned cells are nonzero.
    return [[2 if a[r][c] != 0 and b[r][c] != 0 else 0
             for c in range(len(a[0]))] for r in range(len(a))]
